import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>照片拍歪了，是最常见的图片问题。打开手机里刚拍的照片，却发现地平线变成了竖的；或者扫描的文件上下颠倒，根本没法读。</p>\n<p>旋转和翻转，就是解决这两个问题的办法。旋转是把整张图片转一个角度；翻转是把图片左右或上下镜像。</p>\n<p>这篇指南会用大白话把两种操作讲清楚。你会学到该用哪个角度、怎么修正镜像自拍、为什么有些照片会自己转歪，以及怎么把拍斜的照片拉直还不丢边角。动手的时候，<a href=\"/zh/xuanzhuan-fanzhuan-tupian/\">图片旋转与翻转</a>可以直接在浏览器里旋转和翻转照片。</p>\n<h2 id=\"what-rotation-and-flipping-do\">旋转和翻转，到底是干什么的</h2>\n<p>旋转是让图片围绕中心转动。转90度，宽和高会互换，横构图就变成了竖构图；转180度，图片整个上下颠倒。</p>\n<p>翻转和旋转不一样。水平翻转是左右镜像，就像照镜子；垂直翻转是上下镜像。</p>\n<p>两种操作还能组合使用。比如先把照片转90度，再水平翻转，适合处理既歪又镜像的扫描件。</p>\n<p>不管旋转还是翻转，都不会改变颜色、亮度和清晰度。变的只是每个像素的位置，图片本身其他方面完全不变。</p>\n<h2 id=\"why-photos-end-up-sideways\">照片为什么总是歪的</h2>\n<p>手机拍照时，方向是作为一条记录写在文件里的，这就是EXIF信息。相机并没有真正转动像素，只是记了一笔“当时手机是怎么拿的”。</p>\n<p>有些软件会读这条记录，有些则直接忽略。被忽略时，照片就会显示成歪的。</p>\n<p>这就是为什么同一张照片，在相册里看着正常，到了报名表、聊天软件或老旧看图工具里就歪了。</p>\n<p>扫描仪的问题也类似。纸张放反了，扫出来就是反的，而且没有方向记录可以纠正。自拍则是第三种原因：前置摄像头常常保存镜像画面，衣服上的字会反着显示，直到水平翻转才恢复正常。</p>\n<h2 id=\"rotation-angles-explained\">旋转角度详解：90度、180度和自定义角度</h2>\n<p>90度是最常用的角度。竖拍的照片显示成了横的，或者横拍的显示成了竖的，转90度就能解决。</p>\n<p>180度用来处理完全上下颠倒的图片。扫描件放反了、手机拿反了，或者某些老相机保存的图片，都会出现这种情况。</p>\n<p>自定义角度处理的是中间状态。地平线只歪了5度，不需要转一整个直角，用滑杆精确调到需要的度数就行。</p>\n<p>CompressMyPic的旋转工具支持-180度到+180度的自定义角度。旋转时还会自动扩大画布，斜着的图片不会因为旋转而被裁掉边角。</p>\n<h2 id=\"flip-horizontal-vs-vertical\">水平翻转和垂直翻转的区别</h2>\n<p>水平翻转是左右互换。镜像自拍就是靠它修正的：衣服上的字反了、头发分缝跑到另一边，都是水平翻转的活。</p>\n<p>垂直翻转是上下互换，相对少见。主要用来修正某些特殊角度安装的摄像头拍出的上下颠倒画面。</p>\n<p>翻转改变的不只是方向，还会改变图片的意思。翻转后的路牌会反着读，翻转后的地图会指错方向。</p>\n<p>所以翻转要用得谨慎。如果问题只是“哪边朝上”，先旋转；只有图片确实是镜像的，才用翻转。</p>\n<h2 id=\"exif-orientation-basics\">EXIF方向：为什么有些照片会自己转</h2>\n<p>每张手机或相机拍的照片都带有EXIF元数据，其中一个字段记录了拍照时相机的朝向。</p>\n<p>现代相册和浏览器会读取这个字段，正确显示照片。而老旧软件、部分上传表单和一些社交平台会直接跳过它。</p>\n<p>这种“读与不读”的差别，就是同一张照片在手机上正常、在别处歪掉的原因。像素从来没被转过，只是描述它们的备注被忽略了。</p>\n<p>在编辑器里旋转图片可以永久解决这个问题。工具会重写真实的像素，并把方向记录重置，之后在任何看图软件里显示都正常。</p>\n<h2 id=\"formats-and-quality\">格式与画质：旋转后文件会怎样</h2>\n<p>旋转翻转工具支持JPG、PNG、WebP、HEIC、GIF、BMP和SVG，每张最大20MB。导出时可以保持原格式，也可以换成JPG、PNG或WebP。</p>\n<p>转90度或180度，画质几乎没有损失。像素只是重新排列，没有从头重新编码，肉眼看不出差别。</p>\n<p>自定义角度则不同，因为图片要重新渲染到一张新画布上。工具处理得很干净，但JPG如果以较低画质再次保存，会出现轻微发虚。</p>\n<p>需要最清晰的效果时选PNG或WebP，尤其是截图和带文字的图片。普通照片用高画质JPG就够了。</p>\n<h2 id=\"batch-rotation\">一次旋转很多张照片</h2>\n<p>修一张歪照片很快，但一整个文件夹都很费时间。工具支持批量旋转，同样的角度可以一次性应用到队列里的所有图片。</p>\n<p>旅行或活动之后特别用得上：几十张照片方向全错了，一起上传、选一个角度，就能打包下载成ZIP。</p>\n<p>批量模式会对所有文件用同一设置，所以适合问题一致的情况。如果一半要转90度、一半要转270度，那就分成两批处理。</p>\n<p>ZIP里每个文件都会保留自己的原名。也可以只下载其中某一张，单独处理。</p>\n<h2 id=\"straightening-tilted-photos\">拉直拍斜的照片，不丢边角</h2>\n<p>地平线歪了几度，是很小的旋转问题。但人眼对它非常敏感，尤其是风景照和海景照，一眼就能看出来。</p>\n<p>慢慢拖动旋转滑杆，看着地平线一点点变平。通常一两度就够了，预览里能实时看到变化。</p>\n<p>用自定义角度旋转时，画面四个角会出现三角形空缺。工具会自动扩大画布，把整张旋转后的图片都装下，照片本身不会被裁掉。</p>\n<p>这些空缺会根据格式填充：导出JPG时变成纯色，导出PNG时则保持透明。</p>\n<h2 id=\"fixing-mirrored-selfies\">修正镜像自拍</h2>\n<p>前置摄像头给你看的是镜像画面，因为镜子就是这样工作的。有些手机保存的就是镜像版，有些则会保存修正后的版本。</p>\n<p>如果自拍里的文字是反的，点一下水平翻转就行。图片镜像回来，文字立刻恢复正常。</p>\n<p>翻转前要看完整张图片，不只是文字。翻转还会把痣、疤痕、头发分缝换到另一边，整张照片的感觉都会变。</p>\n<p>头像和证件风格的照片，一般用非镜像版更合适。这样别人才会看到真实的你，而不是镜子里的你。</p>\n<h2 id=\"rotate-vs-crop\">先旋转还是先裁剪</h2>\n<p>旋转和裁剪解决的是不同问题，但经常要配合使用。先旋转修正方向，再裁剪收紧构图，这个顺序最顺。</p>\n<p>如果先裁剪后旋转，很可能白费功夫。为横构图裁好的画面，转成竖构图后就不合适了。</p>\n<p>拉直照片再裁剪是很常见的组合。先转几度把地平线拉平，再把旋转产生的空白三角裁掉。</p>\n<p>两个工具都需要的话，旋转后用<a href=\"/zh/caijian-tupian/\">图片裁剪工具</a>继续处理。裁剪工具会原样保留旋转后的像素，只裁掉你选中的边缘。</p>\n<h2 id=\"privacy-local-processing\">隐私：照片全程留在你的设备上</h2>\n<p>旋转完全在浏览器里完成。照片永远不会上传到服务器，这对个人照片、医疗图片或工作文件来说非常重要。</p>\n<p>这比需要上传的工具实在得多。护照扫描件或全家福，没必要为了转个方向就传到看不见的服务器上。</p>\n<p>工具导出时还会清除EXIF位置信息。下载下来的旋转后照片，不再带有拍摄地点的记录。</p>\n<p>修证件和扫描表格时，这个组合特别实用：方向修好了，位置信息也一次清掉了。</p>\n<h2 id=\"common-mistakes\">旋转图片时最容易犯的错</h2>\n<p>最常见的错误是转错方向。需要顺时针转90度的照片，逆时针转完会更歪，所以下载前一定要看预览。</p>\n<p>另一个错误是该旋转时用了翻转。翻转一张歪照片，只会得到一张镜像的歪照片，看起来比原来更奇怪。</p>\n<p>很多人还会忘记：转90度会互换宽和高。为横幅裁好的照片，转完就变成竖构图，可能放不进原来的位置。</p>\n<p>最后，不要反复旋转同一张JPG。每次保存都会损失一点画质，永远从原文件开始旋转，并且只保存一次。</p>\n<h2 id=\"when-to-rotate-vs-reshoot\">什么时候旋转，什么时候重拍</h2>\n<p>旋转只能修正方向，救不了一张本身就拍坏的照片。模糊、曝光失败的照片，转多少次还是模糊、还是曝光失败。</p>\n<p>主体失焦或光线不对时，应该重拍。相机没拍到的细节，任何角度都找不回来。</p>\n<p>照片本身不错、只是方向错了，那就旋转。这就是这个工具存在的意义：快速修复一张好照片。</p>\n<p>文件也一样。扫描清晰、字迹清楚的，只需要旋转；而歪斜、有阴影的扫描件，值得重新放进扫描仪扫一次。</p>\n<h2 id=\"rotating-scanned-receipts\">旋转扫描的发票和表格</h2>\n<p>发票和纸质表格经常被扫歪，尤其是在匆忙塞进扫描仪的时候。横着的发票既难读，也难归档。</p>\n<p>存档之前先把方向修正好。转90度让文字竖直，再用小角度把放歪的发票拉直。</p>\n<p>报销用的扫描件，旋转之后再裁掉周围多余的扫描仪底板。这样得到的文件干净、清晰，附在报销单后面很方便。</p>\n<p>旋转后检查一下数字。预览里能看清的金额和日期，下载后也一样清楚；如果本来就模糊，可能需要重新扫描而不是旋转。</p>\n<h2 id=\"rotation-and-printing\">打印前的旋转</h2>\n<p>打印机认的是像素，不是方向备注。屏幕上看着正常的照片，打印出来可能是歪的，因为文件仍然依赖EXIF信息来正确显示。</p>\n<p>送去打印之前先修正方向。在工具里旋转像素、下载修正后的文件，再用这个版本去打印。</p>\n<p>转90度后要检查尺寸。宽和高互换了，横构图变成竖构图，纸张尺寸可能也要跟着换。</p>\n<p>如果是装裱的照片，先旋转、再按画框比例裁剪。按这个顺序走，构图完整，主体也不会被裁掉。</p>\n<h2 id=\"rotation-file-naming\">旋转后文件的命名和整理</h2>\n<p>旋转后的文件值得起个清楚的名字，尤其是一批一起修的时候。beach-rotated.jpg一眼就能找到，而IMG_4821.jpg什么信息都没有。</p>\n<p>原文件单独放一个文件夹。旋转后的版本用来分享和上传，原文件则是保险，万一要重做旋转还能找回。</p>\n<p>批量旋转时，下载ZIP后按活动或项目名建文件夹解压。几个月后要找某一张照片，整齐的文件夹能省很多时间。</p>\n<p>不要用旋转后的版本覆盖原文件。一旦原文件没了，就没法无损撤销旋转，而且JPG每多保存一次就多损失一点画质。</p>\n<h2 id=\"combining-rotation-with-edits\">旋转与其他编辑的搭配</h2>\n<p>旋转常常是较长编辑流程的第一步，而不是唯一一步。一张歪照片可能还需要裁剪、调亮或改尺寸，才能发出去。</p>\n<p>按合理顺序来：先旋转，再裁剪，然后调亮度或对比度。每一步都建立在上一步的基础上，顺序乱了容易白费功夫。</p>\n<p>旋转后照片可能还需要调亮。光线不好的照片就算转正了还是暗，可以用<a href=\"/zh/tiaozheng-tupian-liangdu/\">图片亮度调节工具</a>处理。</p>\n<p>旋转后的照片如果太大，用<a href=\"/zh/tiaozheng-tupian-chicun/\">图片尺寸调整工具</a>改尺寸。旋转之后再改尺寸，尺寸才能对上新的方向。</p>\n<p>旋转后还需要裁掉边角的话，打开<a href=\"/zh/caijian-tupian/\">图片裁剪工具</a>继续处理。分步骤的操作说明见<a href=\"/zh/blog/ruhe-xuanzhuan-fanzhuan-tupian/\">如何旋转或翻转图片</a>；想深入了解方向问题，可以读<a href=\"/zh/blog/tupian-fangxiang-exif-xuanzhuan-wenti/\">图片方向：EXIF旋转问题详解</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"什么时候该旋转图片，什么时候该翻转？","answer":"图片只是歪了或上下颠倒、内容本身没问题时，用旋转。只有图片是镜像的，比如自拍里的文字是反的，才用翻转。把一张歪照片翻转之后，它还是歪的，所以动手前先看清楚到底是哪种问题。"},{"question":"旋转照片会让文件变大很多吗？","answer":"转90度或180度，文件大小几乎不变，因为像素只是重新排列，没有重新编码。自定义角度会让文件略有变化，因为图片要重新渲染到更大的画布上，但差别通常很小，可以忽略。"},{"question":"为什么照片在相册里正常，传到网站上就歪了？","answer":"你的相册会读取文件里的EXIF方向记录，而网站直接忽略它，只显示原始像素。在工具里旋转图片会重写像素并重置这条记录，之后照片在任何地方显示都正常。"},{"question":"扫描件既歪又上下颠倒，能修吗？","answer":"可以。完全上下颠倒的用180度，横着的用90度。如果扫描件还是镜像的，旋转之后再加一次水平翻转。每做一步都看一下预览，确认文字恢复正常再继续。"},{"question":"地平线只是微微倾斜，该转多少度？","answer":"先从一两度开始，边看预览边调。大多数倾斜的地平线只需要很小的修正，滑杆可以精确到一度。大角度是给明显歪掉的照片准备的，不适合处理轻微倾斜。"},{"question":"旋转图片会清除位置信息吗？","answer":"会。用旋转翻转工具导出时，文件里的EXIF GPS定位信息会被清除。旋转本身会重写像素，导出时也不再保留原来的位置元数据。如果你想保留这些信息，请留好原文件。"}];
